export type CatPose = (typeof CAT_POSES)[number];

export interface CatPoseData {
  /** ตัดภาพที่ขอบกรอบ 200×200 */
  clip: boolean;
  /** element ร่วมของทุกชั้น */
  els: readonly string[];
  /** ภาพนิ่ง: motion ปิด / ลดการเคลื่อนไหว / CSS ไม่โหลด */
  still: string;
  /** แมวขยับจริง 5 เฟรม */
  frames: readonly string[];
}

